import{z as s,x as l,o as B,c as p,q as A,j as r,D as e,d as n,s as t,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"拥堵定价","description":"","frontmatter":{"title":"拥堵定价","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/congestion-pricing.md","filePath":"econ/congestion-pricing.md","lastUpdated":1791063341000}'),d={name:"econ/congestion-pricing.md"};function C(c,E,g,m,D,u){const o=l("Mermaid");return B(),p("div",null,[E[2]||(E[2]=A('<h1 id="拥堵定价" tabindex="-1">拥堵定价 <a class="header-anchor" href="#拥堵定价" aria-label="Permalink to &quot;拥堵定价&quot;">​</a></h1><div class="epigraph"><p>堵车的本质是收费错误：路在最挤的时候免费，等于给最不需要补贴的人发钱。</p><footer>—— 据 Pigou《The Economics of Welfare》(1920)；Vickrey 纽约地铁定价备忘录 (1950s)；Singapore ERP</footer></div><p><a href="/econ/land-value-tax">土地价值税</a>对「不动的东西」收费，本课对「会挤的东西」收费。道路在高峰期是俱乐部品变公共池塘——每个新加入者给所有人添堵。缺口是<strong>拥堵定价</strong>：把出行者强加给他人的时间成本变成他自己面对的价格。本课不建模路网均衡的工程细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一人上路，私人成本是自己的时间+油钱；社会成本还要加上给所有后来者添的边际延误。免费道路下，只要私人成本低于出行价值，路上就一直加人直到大家都慢——<strong>拥挤外部性</strong>。要回答：费率怎么定（Pigouvian 边际延误成本）、收入归谁、分配怎么补。</p><p><span class="marginnote">术语翻译：边际拥堵成本（marginal congestion cost）= 我上这条路给<strong>所有人</strong>（含我自己）增加的延误总和；Pigouvian 税 = 把这个外部成本变成我自己的价格。注意「我加给自己的延误」我自己已经算过，税只该补「加给别人」的部分。</span></p><p><span class="marginnote">数字实例：伦敦拥堵费 2003 年起收 5 英镑/日（现 15），中心区车流降约 15–18%，公交客流升；斯德哥尔摩 2006 试行后拥堵降 20–25%，公投转正。新加坡 ERP 按车种与时段实时调费，是最接近 Pigouvian 理想价的系统。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定价公式：费 = 边际外部延误成本的货币值，随实时流量调整。实施三件套：<strong>识别</strong>（电子收费门架或 GPS 计费）、<strong>差异化</strong>（时段/区域费率）、<strong>替代品先行</strong>（公交运力与班次在收费前提升）。收入去向是政治可行性核心——伦敦补公交，斯德哥尔摩以「还税于民 + 建地铁」打包过公投。</p>',9)),(B(),r(i,null,{default:e(()=>[t(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%B5%8B%E8%BE%B9%E9%99%85%E5%BB%B6%E8%AF%AF%E6%88%90%E6%9C%AC%22%5D%20--%3E%20B%5B%22%E6%8C%89%E6%97%B6%E6%AE%B5%2F%E5%8C%BA%E5%9F%9F%E8%AE%BE%E8%B4%B9%E7%8E%87%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%94%B5%E5%AD%90%E8%AF%86%E5%88%AB%E8%AE%A1%E8%B4%B9%22%5D%0A%20%20C%20--%3E%20D%7B%22%E5%87%BA%E8%A1%8C%E5%86%B3%E7%AD%96%22%7D%0A%20%20D%20--%3E%7C%22%E6%94%B9%E6%97%B6%E9%97%B4%22%7C%20E%5B%22%E9%94%99%E5%B3%B0%22%5D%0A%20%20D%20--%3E%7C%22%E6%94%B9%E6%96%B9%E5%BC%8F%22%7C%20F%5B%22%E5%85%AC%E4%BA%A4%2F%E9%AA%91%E8%A1%8C%22%5D%0A%20%20D%20--%3E%7C%22%E6%94%B9%E8%B7%AF%E7%BA%BF%22%7C%20G%5B%22%E5%88%86%E6%B5%81%22%5D%0A%20%20D%20--%3E%7C%22%E7%85%A7%E6%97%A7%22%7C%20H%5B%22%E4%BB%98%E8%B4%B9%3D%E7%9C%9F%E6%9C%89%E6%80%A5%E4%BA%8B%22%5D%0A%20%20E%20--%3E%20I%5B%22%E6%8B%A5%E5%A0%B5%E4%B8%8B%E9%99%8D%22%5D%0A%20%20F%20--%3E%20I%0A%20%20G%20--%3E%20I%0A%20%20H%20--%3E%20I%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：高峰道路像没有排队价的网红餐厅——门口大排长龙（堵在路上），餐厅却不涨价；拥堵费就是「取号费」，愿付的人直接入座，不愿付的换个时间来，翻台率（道路通行力）反而更高。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"效率机制是需求侧分流沿四个边际展开——时间、方式、路线、是否出行——每一次调整都把「支付意愿最低」的车流从高峰移走，均衡流量降至边际成本定价处。分配机制的账要算全：低收入驾车者付费、低收入公交受益、 cleaner air 的健康收益偏向沿路居民——多数试点再分配净效应偏向中低收入，但「付费才能进城」的直觉阻力远大于账面。动态机制：费率响应式调节（新加坡式）逼近一阶最优；固定费（伦敦式）是二阶近似，高峰外溢到边界街道是它的典型副作用。",-1)),(B(),r(i,null,{default:e(()=>[t(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%B4%B9%E7%8E%87%E6%80%8E%E4%B9%88%E5%AE%9A%3F%22%7D%20--%3E%7C%22%E5%AE%9E%E6%97%B6%E8%B0%83%E8%B4%B9%22%7C%20R%5B%22%E6%96%B0%E5%8A%A0%E5%9D%A1%20ERP%3A%20%E9%80%BC%E8%BF%91%E4%B8%80%E9%98%B6%E6%9C%80%E4%BC%98%22%5D%0A%20%20Q%20--%3E%7C%22%E5%9B%BA%E5%AE%9A%E8%B4%B9%22%7C%20S%5B%22%E4%BC%A6%E6%95%A6%3A%20%E4%BA%8C%E9%98%B6%E8%BF%91%E4%BC%BC%22%5D%0A%20%20S%20--%3E%20T%5B%22%E8%BE%B9%E7%95%8C%E8%A1%97%E9%81%93%E5%A4%96%E6%BA%A2%22%5D%0A%20%20U%7B%22%E6%94%B6%E5%85%A5%E5%BD%92%E8%B0%81%3F%22%7D%20--%3E%7C%22%E8%A1%A5%E5%85%AC%E4%BA%A4%22%7C%20V%5B%22%E4%BC%A6%E6%95%A6%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20U%20--%3E%7C%22%E8%BF%98%E6%B0%91%2B%E5%9F%BA%E5%BB%BA%22%7C%20W%5B%22%E6%96%AF%E5%BE%B7%E5%93%A5%E5%B0%94%E6%91%A9%E5%85%AC%E6%8A%95%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20V%20--%3E%20X%5B%22%E6%94%BF%E6%B2%BB%E5%8F%AF%E8%A1%8C%E6%80%A7%E6%98%AF%E7%AC%AC%E4%BA%8C%E9%81%93%E9%A2%98%22%5D%0A%20%20W%20--%3E%20X%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">常见误区：把拥堵费当「财政创收工具」——设计目标是<strong>减少拥堵</strong>，最优情形下收入应趋于零（没人堵了）；以收入为目标会故意维持拥堵。另一误区是只收费不给替代品——斯德哥尔摩先加 200 辆公交再收费，顺序颠倒民调即翻车。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>适用前提：拥堵源主要是小汽车、替代方式存在、识别技术可靠。失效场景：收费区边界的「绕行污染」、货车转嫁成本至物价、低收入刚需通勤者的支付能力。公平性修正工具：对区内核准居民的折扣（伦敦 90%）、低收入返款、按里程而非按次计费。更广的视角：拥堵定价是「对使用外部性收费」的模板，机场起降时刻、电网峰谷电价、云平台带宽同构——<a href="/econ/land-value-tax">土地价值税</a>管存量红利，本课管流量外部性，两块拼图合成城市财政的完整图景。</p><p><span class="marginnote">直觉类比：好的拥堵费像好的闹钟——目的不是叫你付钱，是让你改时间；一旦大家都准点（不堵了），闹钟（收费）自然响得越来越少。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>费率 = 边际外部延误成本，实时差异化逼近一阶最优。</li><li>四个分流边际：时间、方式、路线、出行与否。</li><li>政治可行性与效率同等重要：替代品先行 + 收入归属明确。</li><li>出处：Pigou 1920；Vickrey 1950s 备忘录；Singapore LTA ERP 文档；Stockholm 2006 评估报告。</li></ul>',6))])}const F=s(d,[["render",C]]);export{f as __pageData,F as default};
